  if (span.prompt_tokens != null) attributes.push({ key: "llm.usage.prompt_tokens", value: { intValue: span.prompt_tokens } });
  if (span.completion_tokens != null) attributes.push({ key: "llm.usage.completion_tokens", value: { intValue: span.completion_tokens } });
  if (span.cost_usd != null) attributes.push({ key: "llm.usage.cost_usd", value: { doubleValue: span.cost_usd } });
